.cs-splash-button {
  position: fixed;
  bottom: 18px;
  right: 18px;
  z-index: 99;
  padding: 12px 16px;
  border-radius: 14px;
  border: 1px solid rgba(244, 63, 94, 0.6);
  background: linear-gradient(135deg, rgba(244, 63, 94, 0.9), rgba(59, 130, 246, 0.9));
  color: #f8fafc;
  font-weight: 700;
  box-shadow: 0 10px 40px rgba(244, 63, 94, 0.35);
  cursor: pointer;
  transition: transform 140ms ease, box-shadow 140ms ease;
}
.cs-splash-button:hover {
  transform: translateY(-2px) scale(1.02);
  box-shadow: 0 14px 46px rgba(59, 130, 246, 0.38);
}
.cs-splash-overlay {
  position: fixed;
  inset: 0;
  background: radial-gradient(circle at 20% 20%, rgba(59, 130, 246, 0.16), transparent 38%), radial-gradient(circle at 80% 0%, rgba(236, 72, 153, 0.22), transparent 30%), rgba(6, 12, 34, 0.92);
  backdrop-filter: blur(4px);
  display: none;
  align-items: center;
  justify-content: center;
  z-index: 98;
}
.cs-splash-overlay[data-open='true'] {
  display: flex;
}
.cs-splash-panel {
  width: min(900px, 92vw);
  max-height: 86vh;
  overflow: auto;
  padding: 22px;
  border-radius: 20px;
  background: linear-gradient(140deg, rgba(255, 255, 255, 0.04), rgba(15, 23, 42, 0.9));
  border: 1px solid rgba(148, 163, 184, 0.45);
  box-shadow: 0 30px 80px rgba(0, 0, 0, 0.45);
  color: #e2e8f0;
}
.cs-splash-grid {
  display: grid;
  gap: 14px;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
}
.cs-splash-card {
  padding: 14px;
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.05);
  border: 1px solid rgba(255, 255, 255, 0.08);
}
.cs-splash-title {
  font-size: 1.2rem;
  margin-bottom: 6px;
  font-weight: 700;
}
.cs-splash-metric {
  font-size: 1.8rem;
  font-weight: 800;
}
.cs-splash-actions {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  margin-top: 8px;
}
.cs-splash-pill {
  padding: 6px 10px;
  border-radius: 999px;
  border: 1px solid rgba(236, 72, 153, 0.5);
  color: #fce7f3;
  font-size: 0.85rem;
}
.cs-splash-close {
  position: absolute;
  top: 12px;
  right: 18px;
  border: none;
  background: transparent;
  color: #f8fafc;
  font-size: 1.5rem;
  cursor: pointer;
}
.cs-splash-greeting {
  margin-bottom: 10px;
  opacity: 0.86;
}

